package com.ironlootfilter;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

/**
 * Display preferences, stored by RuneLite so they survive a restart.
 * <p>
 * Nothing here changes what the account is allowed to pick up; the settings only decide how much
 * of what the server has already refused is drawn or offered.
 */
@ConfigGroup(IronLootFilterConfig.GROUP)
public interface IronLootFilterConfig extends Config
{
	String GROUP = "ironlootfilter";

	@ConfigItem(
		keyName = "hideModels",
		name = "Hide the item models",
		description = "Stop drawing piles that hold nothing you can pick up. A pile holding one of"
			+ " your own items stays visible until that item is gone",
		position = 0
	)
	default boolean hideModels()
	{
		return true;
	}

	@ConfigItem(
		keyName = "hideMenuEntries",
		name = "Remove the take options",
		description = "Drop Take entries for items you cannot pick up, so left click falls through to"
			+ " whatever is underneath and they never appear on right click",
		position = 1
	)
	default boolean hideMenuEntries()
	{
		return true;
	}

	@ConfigItem(
		keyName = "hideExamine",
		name = "Remove examine too",
		description = "Also drop the Examine entry for those items",
		position = 2
	)
	default boolean hideExamine()
	{
		return true;
	}

	@ConfigItem(
		keyName = "groupDropsTakeable",
		name = "Group drops are takeable",
		description = "Treat group owned items as yours. Turn this off if you are not a group ironman"
			+ " and still see group owned items you cannot take",
		position = 3
	)
	default boolean groupDropsTakeable()
	{
		return true;
	}

	@ConfigItem(
		keyName = "testOnNormalAccount",
		name = "Filter on a normal account",
		description = "Apply the ironman rules on an account that has no restrictions. Only useful for"
			+ " checking the plugin works before taking it to an ironman",
		position = 4
	)
	default boolean testOnNormalAccount()
	{
		return false;
	}
}

package com.ironlootfilter;

import com.google.inject.Provides;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.*;
import net.runelite.api.events.*;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.callback.RenderCallback;
import net.runelite.client.callback.RenderCallbackManager;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

@PluginDescriptor(name = "Iron Loot Filter", description = "Hides ground loot your account cannot pick up. Covers every ironman type; group ironmen keep seeing their group's drops", tags = {"ironman", "iron", "uim", "hcim", "gim", "group", "ground", "items", "loot", "hide", "clutter"})
public class IronLootFilterPlugin extends Plugin
{
    private static final int ABSENT = 0, TAKEABLE = 1, BLOCKED = 2;

    @Inject private Client client;
    @Inject private ClientThread clientThread;
    @Inject private IronLootFilterConfig config;
    @Inject private RenderCallbackManager renderCallbacks;
    /** Read from the render path, replaced wholesale on the client thread. */
    private volatile Rules rules = Rules.INACTIVE;
    private volatile boolean stale = true;

    /**
     * An ItemLayer is a TileObject rather than a Renderable, so it arrives through drawObject and
     * never through addEntity. It carries the items it is about to draw, so the decision is made
     * here from live state: a setting change or a pile changing hands shows up on the next frame
     * with nothing to recalculate or invalidate.
     */
    private final RenderCallback renderCallback = new RenderCallback()
    {
        @Override public boolean drawObject(Scene scene, TileObject object)
        { return !(object instanceof ItemLayer) || drawLayer((ItemLayer) object); }
    };

    @Provides IronLootFilterConfig provideConfig(ConfigManager configManager)
    { return configManager.getConfig(IronLootFilterConfig.class); }

    @Override protected void startUp()
    {
        stale = true;
        renderCallbacks.register(renderCallback);
        clientThread.invoke(this::apply);
    }
    @Override protected void shutDown()
    {
        renderCallbacks.unregister(renderCallback);
        rules = Rules.INACTIVE;
    }

    // Settings arrive on the Swing thread and a slider or a spammed checkbox can post several in a
    // row, so the change is only flagged here and picked up once on the next client tick.
    @Subscribe public void onConfigChanged(ConfigChanged event)
    {
        if (IronLootFilterConfig.GROUP.equals(event.getGroup())) stale = true;
    }
    @Subscribe public void onVarbitChanged(VarbitChanged event)
    {
        if (event.getVarbitId() == VarbitID.IRONMAN) stale = true;
    }
    @Subscribe public void onGameStateChanged(GameStateChanged event)
    {
        stale = true;
    }
    @Subscribe public void onClientTick(ClientTick event)
    {
        if (stale) apply();
    }
    @Subscribe public void onMenuEntryAdded(MenuEntryAdded event)
    {
        Rules current = rules;
        if (!current.active || !current.hideMenuEntries) return;
        MenuEntry entry = event.getMenuEntry();
        MenuAction type = entry.getType();
        if (!isGroundItemAction(type)) return;
        if (type == MenuAction.EXAMINE_ITEM_GROUND && !current.hideExamine) return;
        if (isBlocked(entry.getParam0(), entry.getParam1(), entry.getIdentifier(), current)) client.getMenu().removeMenuEntry(entry);
    }

    /** Client thread only. */
    private void apply()
    {
        stale = false;
        int accountType = client.getGameState() == GameState.LOGGED_IN ? client.getVarbitValue(VarbitID.IRONMAN) : Takeable.NORMAL_ACCOUNT;
        boolean active = Takeable.isRestricted(accountType) || config.testOnNormalAccount();
        rules = active ? new Rules(true, config.hideModels(), config.hideMenuEntries(), config.hideExamine(), config.groupDropsTakeable()) : Rules.INACTIVE;
    }

    /**
     * A pile draws at most three items, and those are the only ones on screen to hide. A tile
     * holding anything still takeable is left alone; once that item goes, the next frame hides
     * what remains.
     */
    private boolean drawLayer(ItemLayer layer)
    {
        Rules current = rules;
        if (!current.active || !current.hideModels) return true;
        int bottom = verdict(layer.getBottom(), current), middle = verdict(layer.getMiddle(), current), top = verdict(layer.getTop(), current);
        if (bottom == TAKEABLE || middle == TAKEABLE || top == TAKEABLE) return true;
        return bottom != BLOCKED && middle != BLOCKED && top != BLOCKED;
    }

    private static int verdict(Renderable renderable, Rules rules)
    {
        if (!(renderable instanceof TileItem)) return ABSENT;
        return Takeable.canTake(true, ((TileItem) renderable).getOwnership(), rules.groupDropsTakeable) ? TAKEABLE : BLOCKED;
    }

    /**
     * A menu entry carries the item ID but not the stack, so a tile holding two stacks of one ID
     * under different owners cannot be told apart. The entry is kept in that case.
     */
    private boolean isBlocked(int sceneX, int sceneY, int itemId, Rules current)
    {
        WorldView view = client.getTopLevelWorldView(); if (view == null) return false;
        Scene scene = view.getScene(); if (scene == null) return false;
        Tile[][][] tiles = scene.getTiles();
        int plane = view.getPlane();
        if (plane < 0 || plane >= tiles.length || sceneX < 0 || sceneX >= tiles[plane].length || sceneY < 0 || sceneY >= tiles[plane][sceneX].length) return false;
        Tile tile = tiles[plane][sceneX][sceneY]; if (tile == null) return false;
        List<TileItem> items = tile.getGroundItems(); if (items == null) return false;
        boolean blocked = false;
        for (int i = 0; i < items.size(); i++)
        {
            TileItem item = items.get(i);
            if (item.getId() != itemId) continue;
            if (Takeable.canTake(true, item.getOwnership(), current.groupDropsTakeable)) return false;
            blocked = true;
        }
        return blocked;
    }

    private static boolean isGroundItemAction(MenuAction action)
    {
        switch (action)
        {
            case GROUND_ITEM_FIRST_OPTION:
            case GROUND_ITEM_SECOND_OPTION:
            case GROUND_ITEM_THIRD_OPTION:
            case GROUND_ITEM_FOURTH_OPTION:
            case GROUND_ITEM_FIFTH_OPTION:
            case WIDGET_TARGET_ON_GROUND_ITEM:
            case EXAMINE_ITEM_GROUND:
                return true;
            default:
                return false;
        }
    }

    /** One snapshot so the render path reads a consistent set rather than five separate fields. */
    private static final class Rules
    {
        static final Rules INACTIVE = new Rules(false, false, false, false, false);
        final boolean active, hideModels, hideMenuEntries, hideExamine, groupDropsTakeable;
        Rules(boolean active, boolean hideModels, boolean hideMenuEntries, boolean hideExamine, boolean groupDropsTakeable)
        { this.active = active; this.hideModels = hideModels; this.hideMenuEntries = hideMenuEntries; this.hideExamine = hideExamine; this.groupDropsTakeable = groupDropsTakeable; }
    }
}

package com.ironlootfilter;

import net.runelite.api.TileItem;

/**
 * Pickup rules, kept away from the client so they can be tested.
 * <p>
 * The server sends an ownership flag with every ground item, and that flag is the same thing the
 * server consults when it decides whether a pickup is allowed. Enumerating the sources of loot
 * instead - player drops, monster drops, raid supplies, ashes from a fire that burnt out - would
 * mean reimplementing that decision badly and rechecking it after every game update, so nothing
 * here looks at item IDs or locations.
 */
final class Takeable
{
    static final int NORMAL_ACCOUNT = 0;

    private Takeable() { }

    static boolean isRestricted(int accountType)
    { return accountType != NORMAL_ACCOUNT; }

    static boolean canTake(boolean restricted, int ownership, boolean groupDropsTakeable)
    {
        if (!restricted) return true;
        switch (ownership)
        {
            case TileItem.OWNERSHIP_OTHER: return false;
            case TileItem.OWNERSHIP_GROUP: return groupDropsTakeable;
            // OWNERSHIP_SELF, plus OWNERSHIP_NONE for world spawns and anything the server never
            // attributed to a player.
            default: return true;
        }
    }
}

package com.ironlootfilter;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.ArrayList;
import java.util.List;
import static org.junit.Assert.assertTrue;
import org.junit.BeforeClass;
import org.junit.Test;

/**
 * The README says what this plugin does not do. These assert it against the source, so a later
 * change that quietly breaks one of those claims fails the build rather than the review.
 */
public class ComplianceTest
{
    private static final List<String> sources = new ArrayList<>();

    @BeforeClass public static void readSource() throws IOException
    {
        Path root = Paths.get("src", "main", "java");
        try (DirectoryStream<Path> files = Files.newDirectoryStream(root.resolve("com/ironlootfilter"), "*.java"))
        {
            for (Path file : files) sources.add(new String(Files.readAllBytes(file), StandardCharsets.UTF_8));
        }
        assertTrue("no sources found", sources.size() >= 3);
    }

    private static void absent(String... fragments)
    {
        for (String source : sources)
            for (String fragment : fragments)
                assertTrue(fragment + " appears in the plugin source", !source.contains(fragment));
    }

    @Test public void makesNoNetworkRequests()
    { absent("java.net", "HttpURLConnection", "Socket", "OkHttp", "openConnection"); }

    @Test public void readsAndWritesNoFiles()
    { absent("java.io.File", "java.nio.file", "FileOutputStream", "FileInputStream", "RUNELITE_DIR"); }

    @Test public void usesNoReflection()
    { absent("java.lang.reflect", "setAccessible", "Class.forName"); }

    @Test public void startsNoThreads()
    { absent("new Thread", "Executors.", "ScheduledExecutorService", "ForkJoin"); }

    @Test public void neverActsForThePlayer()
    { absent("invokeMenuAction", "menuAction(", "createMenuEntry", "java.awt.Robot", "dispatchEvent"); }
}

package com.ironlootfilter;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class IronLootFilterPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(IronLootFilterPlugin.class);
		RuneLite.main(args);
	}
}

package com.ironlootfilter;

import static net.runelite.api.TileItem.OWNERSHIP_GROUP;
import static net.runelite.api.TileItem.OWNERSHIP_NONE;
import static net.runelite.api.TileItem.OWNERSHIP_OTHER;
import static net.runelite.api.TileItem.OWNERSHIP_SELF;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class TakeableTest
{
	private static final int IRONMAN = 1;
	private static final int ULTIMATE_IRONMAN = 2;
	private static final int HARDCORE_IRONMAN = 3;
	private static final int GROUP_IRONMAN = 4;
	private static final int HARDCORE_GROUP_IRONMAN = 5;
	private static final int UNRANKED_GROUP_IRONMAN = 6;

	@Test
	public void normalAccountsAreNotRestricted()
	{
		assertFalse(Takeable.isRestricted(Takeable.NORMAL_ACCOUNT));
	}

	@Test
	public void everyIronmanVariantIsRestricted()
	{
		assertTrue(Takeable.isRestricted(IRONMAN));
		assertTrue(Takeable.isRestricted(ULTIMATE_IRONMAN));
		assertTrue(Takeable.isRestricted(HARDCORE_IRONMAN));
		assertTrue(Takeable.isRestricted(GROUP_IRONMAN));
		assertTrue(Takeable.isRestricted(HARDCORE_GROUP_IRONMAN));
		assertTrue(Takeable.isRestricted(UNRANKED_GROUP_IRONMAN));
	}

	@Test
	public void unrestrictedAccountsTakeAnything()
	{
		assertTrue(Takeable.canTake(false, OWNERSHIP_OTHER, true));
		assertTrue(Takeable.canTake(false, OWNERSHIP_OTHER, false));
	}

	@Test
	public void otherPlayersDropsAreBlocked()
	{
		assertFalse(Takeable.canTake(true, OWNERSHIP_OTHER, true));
		assertFalse(Takeable.canTake(true, OWNERSHIP_OTHER, false));
	}

	@Test
	public void ownDropsAreAllowed()
	{
		assertTrue(Takeable.canTake(true, OWNERSHIP_SELF, true));
	}

	@Test
	public void unownedItemsAreAllowed()
	{
		// Spawns, and ashes left behind by a fire that burnt out.
		assertTrue(Takeable.canTake(true, OWNERSHIP_NONE, true));
		assertTrue(Takeable.canTake(true, OWNERSHIP_NONE, false));
	}

	@Test
	public void groupItemsFollowTheSetting()
	{
		assertTrue(Takeable.canTake(true, OWNERSHIP_GROUP, true));
		assertFalse(Takeable.canTake(true, OWNERSHIP_GROUP, false));
	}
}
